#define NULL 0
#define assert(x) ((void)0)

struct vector3d {
    float x, y, z;
    vector3d operator*(float value) const {
        vector3d result = { x * value, y * value, z * value };
        return result;
    }
    vector3d &operator+=(const vector3d &value) {
        x += value.x; y += value.y; z += value.z;
        return *this;
    }
};

extern float TIMER_FrameSec;
extern float TIMER_LevelSec;
inline float TIMER_GetFrameSec(void) { return TIMER_FrameSec; }
inline float TIMER_GetLevelSec(void) { return TIMER_LevelSec; }
extern void WAVE_GlobalCurrent(vector3d *current);
extern float WAVE_GetScheduleSec(void);

class kellyslater_controller;
class game {
public:
    int get_game_mode(void);
    int get_active_player(void);
};
class world_dynamics_system {
public:
    kellyslater_controller *get_ks_controller(int player);
};
extern game *g_game_ptr;
extern world_dynamics_system *g_world_ptr;
enum { GAME_MODE_CAREER = 0 };

class IconChallenge { public: void Update(float dt); };
class PhotoChallenge { public: void Update(float dt); };

class beach_object {
public:
    virtual ~beach_object();
    virtual void spawn() = 0;
    virtual void despawn() = 0;
    virtual bool update(float dt) = 0;
    virtual bool parse_params(char **argp, int argc);
    virtual void get_settings(const beach_object &obj);
    virtual void collide(void *ent, const vector3d &dir);
    virtual void jumped_over(void *ent);
    virtual void sprayed(void *ent);
    virtual bool is_surfing_object();
    beach_object *next;
    float spawn_time;
    int timer_type;
    int times_spawned;
    bool spawned;
    bool smashable;
    bool active;
    bool never_despawn;
    bool is_active() const { return active; }
};

class beach {
    char judges[696];
public:
    vector3d travel_distance;
    beach_object *my_objects;
protected:
    int current_breakmap;
    int num_breakmap;
    void *smashedEntity;
    struct BeachChallenges { IconChallenge *icon; PhotoChallenge *photo; } challenges;
    void check_challenges(kellyslater_controller *ksctrl);
public:
    void update(float dt);
};

void beach::update (float dt)
{
	vector3d current;

	WAVE_GlobalCurrent (&current);

	travel_distance += current * TIMER_GetFrameSec ();
	float level_time = TIMER_GetLevelSec();
	float wave_time = WAVE_GetScheduleSec();

	if (g_game_ptr->get_game_mode() == GAME_MODE_CAREER)
		check_challenges(g_world_ptr->get_ks_controller(g_game_ptr->get_active_player()));    // Active Player s/b 0 in 1-player game

	// Update every beach object.
	for (beach_object *fobj = my_objects; fobj != NULL; fobj = fobj->next)
	{
		if (!fobj->is_active ())
			continue;

		bool timetospawn = false;

		if (fobj->timer_type == -1) // timed relative to level start
		{
			timetospawn = (fobj->spawn_time < level_time) && (fobj->times_spawned == 0);
		}
		else // timed relative to this wave's start
		{
			assert(fobj->timer_type == current_breakmap);
			timetospawn = (fobj->spawn_time < wave_time);
		}

		if (fobj->spawned)
		{
			if (!fobj->update (dt))
			{
				fobj->active = false;
				fobj->despawn ();
			}
		}
		else
		{
			if (timetospawn)
				fobj->spawn ();
		}
	}

	// Update complex challenges.
	if (challenges.icon) challenges.icon->Update(dt);
	if (challenges.photo) challenges.photo->Update(dt);
}
